import{_ as d,o as e,c as a,a5 as r}from"./chunks/framework.Bhkz_BpM.js";const u=JSON.parse('{"title":"硬件验证指南","description":"","frontmatter":{"date":"2026-06-11T00:00:00.000Z","section":"电机控制","category":"电机控制","source":"motor","visibility":"public","title":"硬件验证指南","tags":["motor-control"],"status":"learning","summary":"本指南定义 lxfoc 与电源专题进入实测闭环时的最低硬件验证要求。"},"headers":[],"relativePath":"content/motor/hardware-validation-guide.md","filePath":"content/motor/hardware-validation-guide.md","lastUpdated":1783096495000}'),i={name:"content/motor/hardware-validation-guide.md"};function l(o,t,c,n,h,s){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="硬件验证指南" tabindex="-1">硬件验证指南 <a class="header-anchor" href="#硬件验证指南" aria-label="Permalink to &quot;硬件验证指南&quot;">​</a></h1><p>本指南定义 lxfoc 与电源专题进入实测闭环时的最低硬件验证要求。</p><h2 id="默认平台" tabindex="-1">默认平台 <a class="header-anchor" href="#默认平台" aria-label="Permalink to &quot;默认平台&quot;">​</a></h2><p>70% 阶段默认从低压 PMSM 平台开始：</p><div class="kb-table-scroll"><table><thead><tr><th>项目</th><th>建议范围</th></tr></thead><tbody><tr><td>母线电压</td><td>12 V 到 60 V</td></tr><tr><td>电机</td><td>小功率 PMSM/BLDC</td></tr><tr><td>电流采样</td><td>至少两相，已标定零偏和增益</td></tr><tr><td>位置传感器</td><td>编码器优先，无感算法需同时记录参考角度</td></tr><tr><td>通信</td><td>串口、USB CDC 或 CAN 转 CSV</td></tr><tr><td>保护</td><td>过流、欠压、过压、急停可验证</td></tr></tbody></table></div><p>高压 PFC、Vienna、LLC 等专题先做仿真和低风险台架，不默认要求直接接入 lxfoc 主库。</p><h2 id="lxfoc-基础算法验收" tabindex="-1">lxfoc 基础算法验收 <a class="header-anchor" href="#lxfoc-基础算法验收" aria-label="Permalink to &quot;lxfoc 基础算法验收&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>算法</th><th>指标</th><th>默认阈值</th></tr></thead><tbody><tr><td>Clarke/Park/SVPWM</td><td>duty 合法、dq 方向正确</td><td>duty 100% 在 <code>[0,1]</code></td></tr><tr><td>电流 PI</td><td>超调、稳定时间、稳态误差</td><td><code>&lt;15%</code>、<code>&lt;5 ms</code>、<code>&lt;3%</code></td></tr><tr><td>有感 FOC</td><td>速度阶跃和故障状态</td><td>无误触发、无 duty 越界</td></tr><tr><td>V/F 与 I/F</td><td>启动方向、电流保护</td><td>方向正确，保护有效</td></tr><tr><td>观测器</td><td>编码器角度对比</td><td>中高速稳态电角误差 <code>&lt;5 deg</code></td></tr></tbody></table></div><h2 id="实验记录" tabindex="-1">实验记录 <a class="header-anchor" href="#实验记录" aria-label="Permalink to &quot;实验记录&quot;">​</a></h2><p>每次实验必须保留：</p><ol><li><code>experiment_manifest.json</code></li><li><code>lxfoc_trace.csv</code></li><li><code>lxfoc_report.json</code></li><li>硬件照片或连接说明</li><li>采样链路标定方法</li><li>异常和失败记录</li></ol><h2 id="安全规则" tabindex="-1">安全规则 <a class="header-anchor" href="#安全规则" aria-label="Permalink to &quot;安全规则&quot;">​</a></h2><ul><li>首次上电必须限流。</li><li>首次闭环必须限转矩、限速度。</li><li>高压实验必须隔离、放电、单手操作和急停。</li><li>任何保护误触发都应保留 trace，不应直接删除。</li><li>无法确认电流采样极性时，不得进入闭环电流控制。</li></ul><h2 id="从-reviewed-到-verified" tabindex="-1">从 reviewed 到 verified <a class="header-anchor" href="#从-reviewed-到-verified" aria-label="Permalink to &quot;从 reviewed 到 verified&quot;">​</a></h2><p>模块升级为 <code>verified</code> 必须同时满足：</p><ol><li>proof 检查通过。</li><li>实测 trace 可导入电控知识库工具链。</li><li>报告指标满足模块阈值。</li><li>至少一次人工复核确认实验条件可信。</li><li>页面标注硬件平台和适用边界。</li></ol>',16)])])}const b=d(i,[["render",l]]);export{u as __pageData,b as default};
